#include <pybind11/pybind11.h>
#include <torch/extension.h>
#include "acl/acl.h"
#include "torch_npu/csrc/core/npu/NPUStream.h"
#include "swi_glu_tiling.h"
extern "C" void swi_glu_do_fp32(uint32_t,void*,uint8_t*,uint8_t*,uint8_t*);
extern "C" void swi_glu_do_fp16(uint32_t,void*,uint8_t*,uint8_t*,uint8_t*);
namespace swi_glu_ext {
using LF=void(*)(uint32_t,void*,uint8_t*,uint8_t*,uint8_t*);
pybind11::tuple run_swi_glu(const at::Tensor &x) {
    TORCH_CHECK(x.dim()==2,"x must be [M,2*inter]");
    TORCH_CHECK(x.scalar_type()==at::kFloat||x.scalar_type()==at::kHalf,"unsupported dtype");
    TORCH_CHECK(x.is_contiguous(),"must be contiguous");
    const auto m=static_cast<int32_t>(x.sizes()[0]), twoInter=static_cast<int32_t>(x.sizes()[1]);
    TORCH_CHECK(twoInter%2==0,"last dim must be even");
    const int32_t inter=twoInter/2;
    const int32_t mNum=(m+DEFAULT_BLOCK_M-1)/DEFAULT_BLOCK_M;
    const int32_t uc=std::min<int32_t>(DEFAULT_NUM_PHYSICAL_CORES,mNum);
    const int32_t tpc=(mNum+uc-1)/uc;
    at::Tensor y=at::empty({m,inter},x.options());
    at::Tensor tc=at::empty({static_cast<long>(sizeof(SwiGluKernelTiling))},at::device(at::kCPU).dtype(at::kByte));
    auto *t=reinterpret_cast<SwiGluKernelTiling*>(tc.data_ptr());
    t->M=m; t->N=twoInter; t->blockM=DEFAULT_BLOCK_M; t->usedCoreNum=uc; t->tasksPerCore=tpc;
    auto tn=tc.to(at::kPrivateUse1);
    auto stm=c10_npu::getCurrentNPUStream().stream(false);
    LF l=nullptr;
    if(x.scalar_type()==at::kFloat) l=swi_glu_do_fp32;
    else if(x.scalar_type()==at::kHalf) l=swi_glu_do_fp16;
    else TORCH_CHECK(false,"unsupported");
    l(uc,stm,static_cast<uint8_t*>(const_cast<void*>(x.storage().data())),static_cast<uint8_t*>(const_cast<void*>(y.storage().data())),static_cast<uint8_t*>(const_cast<void*>(tn.storage().data())));
    return pybind11::make_tuple(y);
}}
PYBIND11_MODULE(_swi_glu_ext, m) { m.def("run_swi_glu",&swi_glu_ext::run_swi_glu,""); }

