extern "C" __global__ __aicore__ void swi_glu_custom_fp16(GM_ADDR x, GM_ADDR y, GM_ADDR t) {
    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_MIX_AIC_1_2); AscendC::TPipe p;
    SwiGluKernel<half> k; k.Init(x, y, t, &p); k.Process();
}
